(() => {
 'use strict';
 if(!document.documentElement.dataset.nkRouteDocument&&!(window!==window.parent&&new URL(location.href).searchParams.has('nk_frame'))&&!new URL(location.href).searchParams.has('nk_direct'))return;
 const $ = (q,root=document) => root.querySelector(q);
 const $$ = (q,root=document) => [...root.querySelectorAll(q)];
 const menu=$('#site-menu'),toggle=$('.menu-toggle');
 let lastFocus;
 function closeMenu(){if(!menu)return;document.body.classList.remove('menu-open');menu.inert=true;toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open menu');}
 function openMenu(){lastFocus=document.activeElement;document.body.classList.add('menu-open');menu.inert=false;toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','Close menu');menu.querySelector('a').focus();}
 toggle?.addEventListener('click',()=>document.body.classList.contains('menu-open')?closeMenu():openMenu());
 $$('#site-menu a').forEach(a=>a.addEventListener('click',closeMenu));
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('menu-open')){closeMenu();lastFocus?.focus();}if(e.key==='Tab'&&document.body.classList.contains('menu-open')){const nodes=[toggle,...$$('a,button',menu)],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 const dialog=$('#brand-dialog');
 const notes={
  custody:{kicker:'01 / THE FOUNDATION',title:'Two places. A clear line.',body:'<p>Your Noklith account is controlled by your keys. Slabs organize money inside that account. The card is a separate product, issued under a card program’s own terms.</p><p>When you move money to a card, it is held in that card program. It is no longer in your keys. The idea is simple: keep only your pocket money there, with your wider balance in your account.</p><p>Card programs can freeze or close cards and change their terms. Your account remains separate. A balance on a card follows that card’s terms, including expiry and any restrictions on returning funds.</p>'},
  float:{kicker:'02 / A NATURAL RHYTHM',title:'Just enough. By your rules.',body:'<p>Float is designed around three choices: the amount you want on your card, the point where a refill should happen, and the most that can be moved in a day.</p><p>For example: keep 150 on the card, refill below 40, and stay within a daily cap of 500. These are illustrative settings, not a suggested budget.</p><p>The automation is limited by a signed policy and can be revoked. It depends on the card program’s capabilities. Without a supported balance feed, the app falls back to manual loads. Changed card terms pause automation until accepted again.</p>'},
  desk:{kicker:'03 / BENEATH THE SURFACE',title:'A path with an outcome.',body:'<p>Card Desk is the proposed on-chain escrow between your account and a card load. Funds enter escrow before a card-program request is made.</p><p>Unaccepted loads can be refunded after 10 minutes. Accepted loads either settle or refund; after 72 hours without an outcome, anyone can trigger the refund path. A failure returns the escrowed amount and fees to the payer.</p><p>The chain can verify escrow states, but it cannot prove the card program credited your card. That boundary requires confirmer signatures, reconciliation, and a claims buffer. The product is being designed to make that distinction visible.</p>'},
  recovery:{kicker:'04 / YOUR WAY BACK',title:'Ownership includes an exit.',body:'<p>A passkey makes everyday access simpler. An optional backup signer, such as a hardware key, provides another way to control the account.</p><p>The design also includes guardian recovery and an independent exit page that can read public network balances and submit a withdrawal without the Noklith API.</p><p>Passkeys are tied to the Noklith domain. If that domain is lost, recovery needs the backup signer or guardians. Network gas may still be needed when sponsorship is unavailable.</p>'},
  preview:{kicker:'PRODUCT & PRIVACY',title:'Your account. Your choices.',body:'<p>Your account connection gives access to balances, money movements, and card services. Availability depends on supported networks, region, and card-program terms.</p><p>Until an account is connected, the dashboard shows an empty account state. Financial actions require a supported account connection.</p><p>Appearance preferences stay in this browser. This website has no newsletter form or analytics integration. Interactive guides explain product rules without accessing an account.</p>'}
 };
 notes.images={"kicker": "THE WORLD BENEATH THE BRAND", "title": "Photography & sources.", "body": "<p>Original prehistoric artwork, new photographs, and natural stone in Noklith’s earth tones.</p><p>Each stock photograph is used once. Complete source credits and licences are available below.</p><a href=\"/photography.html\" class=\"button dark\">VIEW ALL PHOTO CREDITS ↗</a>"};
 function showDialog(kicker,title,body){if(!dialog)return;closeMenu();lastFocus=document.activeElement;$('#dialog-kicker').textContent=kicker;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;dialog.showModal();document.dispatchEvent(new Event('noklith:overlaychange'));parent.postMessage({type:'nk-overlay',open:true},location.origin);$('.dialog-close').focus();}
 $$('[data-social]').forEach(b=>b.addEventListener('click',()=>showDialog('THE NEXT CHAPTER',`${b.dataset.social} is coming soon.`,'<p>We’re still carving out our place. Noklith’s official '+b.dataset.social+' will be shared here when it is ready.</p><p>For now, take a look around and explore Noklith.</p>')));
 $$('[data-note]').forEach(b=>b.addEventListener('click',()=>{const n=notes[b.dataset.note];if(n)showDialog(n.kicker,n.title,n.body)}));
 $$('.dialog-close,.dialog-done').forEach(b=>b.addEventListener('click',()=>dialog.close()));
 dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
 dialog?.addEventListener('close',()=>{document.dispatchEvent(new Event('noklith:overlaychange'));parent.postMessage({type:'nk-overlay',open:false},location.origin);lastFocus?.focus()});
 const values=[['YOUR KEYS FIRST','Your account stays yours. Only your pocket money sits on the card.'],['MONEY WITH A PURPOSE','Give every part of life a Slab. Make space for the things you plan.'],['YOUR RULES, ALWAYS','Set your pace. Choose your limits. Keep the important decisions in your hands.']];let value=0;
 function setValue(n){value=n;const copy=$('#value-copy');if(!copy)return;$('.value-title',copy).textContent=values[n][0];$('p',copy).textContent=values[n][1];$('#value-index').textContent=String(n+1).padStart(2,'0');copy.dispatchEvent(new Event('valuechange'));$$('[data-value]').forEach((b,i)=>b.classList.toggle('active',i===n));}
 $$('[data-value]').forEach(b=>b.addEventListener('click',()=>setValue(Number(b.dataset.value))));
 if(!document.body.classList.contains('landing-page')&&$('#value-copy')&&!matchMedia('(prefers-reduced-motion: reduce)').matches)setInterval(()=>{if(!document.hidden)setValue((value+1)%3)},7000);
 const systems={slabs:{index:'01 / ORGANIZE',title:'Make space for your plans.',description:'Named balances inside your account, each with a purpose. Keep everyday spending, the next trip, and your reserve on their own footing.',graphic:['Everyday','Rent','Reserve'],hash:'slabs'},float:{index:'02 / FIND YOUR RHYTHM',title:'A little. On your terms.',description:'Choose a card balance, a refill threshold, and a daily cap. Float works inside the permissions you sign, and you can revoke it when you want.',graphic:['Your Slab','→','Your Float'],hash:'rules'},shared:{index:'03 / TOGETHER',title:'Shared plans. Clear boundaries.',description:'Shared Slabs are designed for two to five people. Individual limits and co-sign rules keep shared money clear, with each person able to withdraw their own net share.',graphic:['You','Shared Slab','Together'],hash:'slabs'},desk:{index:'04 / A CLEAR PATH',title:'Every load has a path.',description:'Card Desk is designed to hold loads in on-chain escrow until they settle or refund. Time-based refund paths help a failed load find its way back.',graphic:['Escrow','Accept','Settle / refund'],hash:'cards'}};
 const tabs=$$('[data-system]');function selectSystem(key){const s=systems[key];tabs.forEach(b=>{const active=b.dataset.system===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});$('#system-index').textContent='[ '+s.index+' ]';$('#system-title').textContent=s.title;$('#system-description').textContent=s.description;const assets={slabs:['organize-tab','Distinct basalt columns seen from above'],float:['flow-tab','A natural passage through volcanic rock'],shared:['shared-tab','Ancient human figures engraved together in stone'],desk:['card-tab','Experimental flint handaxe replica on a plain field']};const image=document.createElement('img');image.src='/assets/stock-v2/'+assets[key][0]+'.webp';image.alt=assets[key][1];image.width=1920;image.height={slabs:1081,float:909,shared:1285,desk:1280}[key];image.decoding='async';$('#system-graphic').replaceChildren(image);$('#system-link').href='/dashboard.html#'+s.hash;$('#system-panel').setAttribute('aria-labelledby','tab-'+key)}
 tabs.forEach((b,i)=>{b.addEventListener('click',()=>selectSystem(b.dataset.system));b.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+tabs.length)%tabs.length;selectSystem(tabs[j].dataset.system);tabs[j].focus()})});
 if(!document.body.classList.contains('landing-page'))$$('.faq-list details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)$$('.faq-list details').forEach(other=>{if(other!==d)other.open=false})}));
 if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}}),{threshold:.15});$$('.reveal').forEach(el=>observer.observe(el));}
})();
